<?php $title='Replenishment';$subtitle='Suggested quantity = effective reorder point (warehouse override, else product default) minus available stock (on hand minus reserved for approved sales orders) minus open PO supply minus goods in transit to the warehouse, per warehouse. It is computed in the base unit and rounded up to whole purchase units (the product\'s purchase default unit).';$toolbar='<a class="button-primary" href="/purchase-orders/create">Create PO</a>';require __DIR__.'/start.php';$selecting=$filters['warehouse_id']!==''; ?>
<?php if($result!==null && !$selecting): ?><p class="page-subtitle">Choose one warehouse to select several recommendations for a single purchase order.</p><?php endif; ?>
<form method="get" action="/replenishment" class="filters"><label>Search product <input name="q" maxlength="120" value="<?= $escape($filters['q']) ?>"></label>
<label>Warehouse <select name="warehouse_id"><option value="">All warehouses</option><?php foreach($warehouses as $warehouse): ?><option value="<?= $warehouse->id() ?>" <?= $filters['warehouse_id']===(string)$warehouse->id()?'selected':'' ?>><?= $escape($warehouse->name()) ?></option><?php endforeach; ?></select></label>
<button type="submit">Apply Filters</button><a class="button" href="/replenishment">Reset</a></form>
<?php if($result!==null): ?>
<section class="table-scroll" aria-label="Replenishment table"><table class="data-table"><thead><tr><?php if($selecting): ?><th scope="col" data-no-sort>Select</th><?php endif; ?><th>Product</th><th>Warehouse</th><th>Available</th><th>Reorder point</th><th>Open PO supply</th><th>Suggested</th><th>Action</th></tr></thead><tbody>
<?php foreach($result->items() as $row):
    // D-16 / ADR-022: suggested is in base units; the PO line is prefilled with whole purchase-default units, rounded up.
    $base=(string)($row['base_unit']??'');$unit=(string)($row['purchase_unit']??$base);$factor=max(1,(int)($row['purchase_factor']??1));
    $units=\App\Support\UnitSet::unitsCovering((int)$row['suggested'],$factor);$b=static fn($value): string => number_format((int)$value,0,',','.').($base!==''?' '.$base:''); ?><tr><?php if($selecting): ?><td><input type="checkbox" form="replenishment-selection" name="pick[]" value="<?= $escape((int)$row['product_id'].':'.$units.($factor>1?':'.$unit:'')) ?>" aria-label="<?= $escape('Select '.$row['sku']) ?>"></td><?php endif; ?><td><?= $escape($row['sku'].' — '.$row['product_name']) ?></td><td><?= $escape($row['warehouse_name']) ?></td><td><?= $escape($b($row['available_quantity'])) ?><?= (int)$row['reserved_quantity']>0?' <small class="field-hint">'.$escape($b($row['quantity'])).' on hand, '.$escape($b($row['reserved_quantity'])).' reserved</small>':'' ?></td><td><?= $escape($b($row['reorder_point'])) ?><?= ($row['reorder_point_override']??null)!==null?' <small class="field-hint">warehouse</small>':'' ?></td><td><?= $escape($b($row['inbound'])) ?><?= (int)($row['in_transit']??0)>0?' <small class="field-hint">+ '.$escape($b($row['in_transit'])).' in transit</small>':'' ?></td><td data-suggested="<?= (int)$row['suggested'] ?>"><?= $factor>1?$escape($units.' '.$unit).' <small class="field-hint">'.$escape(number_format($units*$factor,0,',','.').' '.$base.'; need '.$b($row['suggested'])).'</small>':$escape($b($row['suggested'])) ?></td><td><a class="action-link" href="<?= $escape('/purchase-orders/create?'.http_build_query(['product_id'=>$row['product_id'],'warehouse_id'=>$row['warehouse_id'],'quantity'=>$units]+($factor>1?['unit_code'=>$unit]:[]))) ?>">Review PO</a></td></tr><?php endforeach; ?>
<?php if($result->total()===0): ?><tr><td colspan="<?= $selecting?8:7 ?>">No products need additional supply.</td></tr><?php endif; ?></tbody></table></section>
<?php $paginationPath='/replenishment';$paginationLabel='Recommendations';$paginationQuery=['q'=>$filters['q'],'warehouse_id'=>$filters['warehouse_id']];require dirname(__DIR__).'/partials/pagination.php'; ?>
<?php if($selecting && $result->total()>0): ?><form method="get" action="/purchase-orders/create" id="replenishment-selection" data-replenishment-selection><input type="hidden" name="warehouse_id" value="<?= $escape($filters['warehouse_id']) ?>"><div class="form-actions"><button type="submit">Review PO for selected</button><span class="page-subtitle">Supplier, quantities and prices are reviewed before the draft is saved.</span></div></form><?php endif; ?>
<?php endif;require __DIR__.'/end.php'; ?>
